398	<body>
399	  <main>
400	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
401	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
402	        <circle cx="200" cy="200" r="200"/>
403	      </svg>
404	    </button>
405	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
406	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
407	    <div class="controls" role="group" aria-label="Circle controls">
408	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
409	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
410	    </div>
411	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
412	  </main>
413	
414	  <script defer>
415	    (() => {
416	      const CONFIG = {
417	        storageKey: 'circle-state',
418	        tapDelay: 300,
419	        colorShiftDuration: 500,
420	        saveDebounceDuration: 100,
421	        colorModes: [
422	          { class: 'default', name: 'Default White' },
423	          { class: 'color-mode-1', name: 'Pink' },
424	          { class: 'color-mode-2', name: 'Teal' },
425	          { class: 'color-mode-3', name: 'Mint' },
426	          { class: 'color-mode-4', name: 'Purple' },
427	          { class: 'color-mode-5', name: 'Orange' }
428	        ],
429	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
430	      };
431	
432	      const el = {
433	        circle: document.getElementById('decorative-circle'),
434	        hint: document.getElementById('hint-text'),
435	        modeIndicator: document.getElementById('mode-indicator'),
436	        cycleBtn: document.getElementById('cycle-btn'),
437	        resetBtn: document.getElementById('reset-btn')
438	      };
439	
440	      let state = { active: false, colorMode: 0 };
441	      let tapCount = 0;
442	      let tapTimeout = null;
443	      let animatingColorShift = false;
444	      let saveTimeout = null;
445	
446	      const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
447	      const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
448	
449	      const storage = {
450	        save() {
451	          clearTimeout(saveTimeout);
452	          saveTimeout = setTimeout(() => {
453	            try {
454	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
455	            } catch (e) {
456	              if (e.name === 'QuotaExceededError') {
457	                console.warn('localStorage quota exceeded');
458	              }
459	            }
460	          }, CONFIG.saveDebounceDuration);
461	        },
462	        load() {
463	          try {
464	            const saved = localStorage.getItem(CONFIG.storageKey);
465	            if (saved) {
466	              const parsed = JSON.parse(saved);
467	              if (parsed && typeof parsed === 'object') {
468	                state = { ...state, ...parsed };
469	              }
470	            }
471	          } catch (e) {
472	            console.warn('Failed to load state from localStorage');
473	          }
474	        }
475	      };
476	
477	      const updateClasses = () => {
478	        const colorClasses = CONFIG.colorModes.map(m => m.class);
479	        el.circle.classList.remove('active', ...colorClasses);
480	        el.circle.setAttribute('aria-pressed', state.active);
481	        if (state.active) el.circle.classList.add('active');
482	        if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
483	      };
484	
485	      const updateUI = () => {
486	        let hintText = '';
487	
488	        if (CONFIG.isTouch) {
489	          hintText = state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle';
490	        } else {
491	          hintText = state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle';
492	        }
493	
494	        el.hint.textContent = hintText;
495	
496	        const showMode = state.active && state.colorMode > 0;
497	        el.modeIndicator.classList.toggle('visible', showMode);
498	        if (showMode) {
499	          const modeName = getColorModeName(state.colorMode);
500	          el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()}`;
501	        }
502	      };
503	
504	      const applyState = () => {
505	        updateClasses();
506	        updateUI();
507	      };
508	
509	      const toggleActive = () => {
510	        state.active = !state.active;
511	        applyState();
512	        storage.save();
513	      };
514	
515	      const cycleColor = () => {
516	        if (animatingColorShift) return;
517	        animatingColorShift = true;
518	        state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
519	        state.active = true;
520	        el.circle.classList.add('color-shifting');
521	        setTimeout(() => {
522	          el.circle.classList.remove('color-shifting');
523	          animatingColorShift = false;
524	        }, CONFIG.colorShiftDuration);
525	        applyState();
526	        storage.save();
527	      };
528	
529	      const resetState = () => {
530	        state = { active: false, colorMode: 0 };
531	        applyState();
532	        storage.save();
533	      };
534	
535	      const handleClick = () => {
536	        if (!CONFIG.isTouch) toggleActive();
537	      };
538	
539	      const handleDblClick = () => {
540	        cycleColor();
541	      };
542	
543	      const handleTouchEnd = () => {
544	        tapCount++;
545	        clearTimeout(tapTimeout);
546	        if (tapCount === 1) {
547	          tapTimeout = setTimeout(() => {
548	            if (tapCount === 1) toggleActive();
549	            tapCount = 0;
550	          }, CONFIG.tapDelay);
551	        } else if (tapCount === 2) {
552	          cycleColor();
553	          tapCount = 0;
554	        }
555	      };
556	
557	      const keyHandlers = {
558	        ' ': toggleActive,
559	        'enter': toggleActive,
560	        'escape': () => {
561	          el.circle.blur();
562	          if (state.active) toggleActive();
563	        },
564	        'c': cycleColor,
565	        'r': resetState
566	      };
567	
568	      const handleKeyDown = (e) => {
569	        const handler = keyHandlers[e.key.toLowerCase()];
570	        if (handler) {
571	          e.preventDefault();
572	          handler();
573	        }
574	      };
575	
576	      const initListeners = () => {
577	        if (CONFIG.isTouch) {
578	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
579	        } else {
580	          el.circle.addEventListener('click', handleClick, { passive: true });
581	          el.circle.addEventListener('dblclick', handleDblClick, { passive: true });
582	        }
583	        el.circle.addEventListener('blur', () => {
584	          tapCount = 0;
585	          clearTimeout(tapTimeout);
586	        });
587	        document.addEventListener('keydown', handleKeyDown);
588	        el.cycleBtn.addEventListener('click', cycleColor, { passive: true });
589	        el.resetBtn.addEventListener('click', resetState, { passive: true });
590	      };
591	
592	      const initApp = () => {
593	        storage.load();
594	        applyState();
595	        initListeners();
596	        el.circle.focus();
597	      };
598	
599	      const ensureSave = () => {
600	        clearTimeout(saveTimeout);
601	        try {
602	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
